#!/bin/bash
# joinlines.sh FILE : print the lines of FILE joined with commas
[ $# -eq 1 ] && [ -r "$1" ] || { echo "usage: joinlines.sh FILE" >&2; exit 2; }
awk 'NR > 1 { printf "," } { printf "%s", $0 } END { if (NR > 0) printf "\n" }' "$1"

