#!/bin/bash
# wrapper.sh CMD [ARG...] : append "+ <command line>" to wrapper.log, then run the command
[ $# -gt 0 ] || { echo "usage: wrapper.sh CMD [ARG...]" >&2; exit 2; }
{ printf '+'; printf ' %q' "$@"; printf '\n'; } >> wrapper.log
"$@"

