            with open(full, "wb") as f:
                f.write(op.get("c", "").encode("utf-8"))
            if "m" in op:
                os.utime(full, (op["m"], op["m"]))
        elif kind == "touch":
            os.utime(full, (op["m"], op["m"]))
        elif kind == "rm":
            if os.path.isdir(full) and not os.path.islink(full):
                shutil.rmtree(full)
            elif os.path.lexists(full):
                os.remove(full)
        elif kind == "mkdir":
            os.makedirs(full, exist_ok=True)
        elif kind == "chmod":
            os.chmod(full, op["mode"])


