#!/bin/bash
# search.sh [-i] [-w] PATTERN FILE... : grep -n with optional flags
args=(-n)
while getopts ':iw' o; do
  case $o in
    i) args+=(-i) ;;
    w) args+=(-w) ;;
    *) echo "usage: search.sh [-i] [-w] PATTERN FILE..." >&2; exit 2 ;;
  esac
done
shift $((OPTIND - 1))
[ $# -ge 2 ] || { echo "usage: search.sh [-i] [-w] PATTERN FILE..." >&2; exit 2; }
pattern=$1
shift
grep "${args[@]}" -e "$pattern" -- "$@"
